def transform(grid):
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    markers = [v for v, n in counts.items() if v != background]
    marker = markers[0]
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Connect the outermost matching markers in each row and column,
    # recoloring intervening background cells to 3.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == marker]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    out[r][c] = 3

